     1|/**
     2| * Blank screen watchdog — the last line of defence against a silent black screen.
     3| *
     4| * Renders nothing in the normal case. If no screen reports a successful paint
     5| * within a bounded window, the route tree resolved to nothing and the user is
     6| * staring at an empty root view. Instead of leaving them with a black frame,
     7| * this shows what happened and offers real recovery actions.
     8| *
     9| * This exists because a "renders nothing" failure throws no error: boundaries,
    10| * the global fatal shield and the crash log are all silent by design.
    11| *
    12| * DEFECT 1 THIS FIXES — the watchdog accused a screen that had painted.
    13| *
    14| * v1.10.23 asked `paintedAt < enteredAt`. Expo Router keeps tab screens mounted,
    15| * so Home reports its paint once and never again, while this component re-armed
    16| * `enteredAt` on every pathname change. Any return to Home therefore compared an
    17| * old paint against a new entry stamp and declared a fully rendered screen blank.
    18| * The device recording caught the contradiction in the overlay's own text:
    19| * `Route: /home` above `Last painted: /home`.
    20| *
    21| * It now asks whether the route holds a LIVE paint record — a mounted screen that
    22| * rendered content — which cannot be defeated by timestamp ordering.
    23| *
    24| * DEFECT 2 THIS FIXES — recovery landed on the same empty container and then
    25| * permanently blinded the watchdog.
    26| *
    27| * `goHome` replaced the current route with Home while the user was ALREADY on
    28| * Home: a no-op navigation that left the identical empty view on screen. It also
    29| * pinned `dismissedRouteRef` to that path forever, so Home could never be judged
    30| * again for the rest of the process. Recovery now bounces through the root route
    31| * so the tab tree genuinely re-resolves, and a dismissal only suppresses the
    32| * current stay on that route.
    33| */
    34|import React, { useCallback, useEffect, useRef, useState } from 'react';
    35|import { StyleSheet, View, Text, TouchableOpacity } from 'react-native';
    36|import { usePathname, useRouter } from 'expo-router';
    37|import {
    38|  getLastPaintedScreen,
    39|  hasRouteFailedToPaint,
    40|  isRouteInstrumented,
    41|} from '@/lib/screen-paint-watchdog';
    42|
    43|/** Root route, used to force a genuine re-resolve of the tab tree. */
    44|const ROOT_ROUTE = '/';
    45|
    46|const BLANK_SCREEN_TIMEOUT_MS = 8000;
    47|
    48|export function BlankScreenWatchdog({ build }: { build: string }) {
    49|  const router = useRouter();
    50|  const pathname = usePathname();
    51|  const [isBlank, setIsBlank] = useState(false);
    52|  const dismissedRouteRef = useRef<string | null>(null);
    53|
    54|  useEffect(() => {
    55|    // A dismissal suppresses only the current stay on that route. Leaving it
    56|    // re-arms the watchdog — v1.10.23 pinned this forever, so one tap on the
    57|    // recovery button made Home permanently unjudgeable.
    58|    if (dismissedRouteRef.current !== null && dismissedRouteRef.current !== pathname) {
    59|      dismissedRouteRef.current = null;
    60|    }
    61|    if (dismissedRouteRef.current === pathname) return;
    62|    // Only judge routes that actually report paint. Accusing an uninstrumented
    63|    // screen of being blank would cover working UI with an error overlay.
    64|    if (!isRouteInstrumented(pathname)) {
    65|      setIsBlank(false);
    66|      return;
    67|    }
    68|
    69|    setIsBlank(false);
    70|
    71|    const timer = setTimeout(() => {
    72|      // Liveness, not freshness: a mounted screen that painted is never accused,
    73|      // however long ago it painted.
    74|      if (hasRouteFailedToPaint(pathname)) {
    75|        console.warn('[IVX] Blank screen watchdog fired — route painted nothing', {
    76|          pathname,
    77|          lastPainted: getLastPaintedScreen(),
    78|        });
    79|        setIsBlank(true);
    80|      }
    81|    }, BLANK_SCREEN_TIMEOUT_MS);
    82|    return () => clearTimeout(timer);
    83|  }, [pathname]);
    84|
    85|  const goHome = useCallback(() => {
    86|    dismissedRouteRef.current = pathname;
    87|    setIsBlank(false);
    88|    try {
    89|      // Replacing the accused route with itself is a no-op that leaves the same
    90|      // empty container on screen — recorded on device as 14 seconds of #0A0A0F
    91|      // after tapping this button. Bounce through the root so the tab tree is
    92|      // genuinely re-resolved and the screen actually remounts.
    93|      const alreadyHome = pathname === '/home' || pathname === '/(tabs)/home';
    94|      router.replace(alreadyHome ? ROOT_ROUTE : '/(tabs)/home');
    95|    } catch (err) {
    96|      console.warn('[IVX] Watchdog home recovery failed', err);
    97|    }
    98|  }, [router, pathname]);
    99|
   100|  const goLogin = useCallback(() => {
   101|    dismissedRouteRef.current = pathname;
   102|    setIsBlank(false);
   103|    try {
   104|      router.replace('/login');
   105|    } catch (err) {
   106|      console.warn('[IVX] Watchdog login recovery failed', err);
   107|    }
   108|  }, [router, pathname]);
   109|
   110|  if (!isBlank) return null;
   111|
   112|  return (
   113|    <View style={styles.overlay} testID="blank-screen-watchdog">
   114|      <Text style={styles.title}>Screen failed to load</Text>
   115|      <Text style={styles.body}>
   116|        The app navigated to a route that rendered no content. No error was thrown, so this
   117|        recovery screen is shown instead of a blank display.
   118|      </Text>
   119|      <Text style={styles.meta}>{`Route: ${pathname || 'unknown'}`}</Text>
   120|      <Text style={styles.meta}>{`Last painted: ${getLastPaintedScreen() ?? 'none'}`}</Text>
   121|      <Text style={styles.meta}>{`Build ${build}`}</Text>
   122|      <TouchableOpacity style={styles.button} onPress={goHome} testID="watchdog-go-home">
   123|        <Text style={styles.buttonText}>Go to Home</Text>
   124|      </TouchableOpacity>
   125|      <TouchableOpacity style={styles.secondary} onPress={goLogin} testID="watchdog-go-login">
   126|        <Text style={styles.secondaryText}>Back to Login</Text>
   127|      </TouchableOpacity>
   128|    </View>
   129|  );
   130|}
